## File 2: `src/errors/CustomError.js`

```javascript
/**
 * CustomError.js — Base class for all custom application errors.
 *
 * WHY we use a base error class instead of plain Error objects:
 *   - It allows us to attach structured metadata (statusCode, isOperational)
 *     that middleware can read without parsing strings.
 *   - It gives us a consistent hierarchy so catch blocks can check instanceof.
 *   - "Operational" errors are expected problems (bad input, not found) vs
 *     "Programmer" errors (bugs like null pointer exceptions).
 */

/**
 * CustomError — Base class extending the built-in Error.
 *
 * @param {string} message — Human-readable error description.
 * @param {number} statusCode — HTTP status code to return to the client.
 * @param {boolean} isOperational — Whether this is an expected runtime issue.
 */
class CustomError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);

    // Capture the stack trace at the point of instantiation (not inside the class).
    // This ensures the stack points to where the error was thrown, not where it's defined.
    Error.captureStackTrace(this, this.constructor);

    this.name = 'CustomError';
    this.statusCode = statusCode;
    this.isOperational = isOperational;
  }
}

/**
 * NotFoundError — Resource does not exist (404).
 *
 * WHY separate class: It lets route handlers throw a specific error type that
 * the global error middleware can distinguish from other errors.
 */
class NotFoundError extends CustomError {
  constructor(resource, id) {
    // "Resource 'books' with ID 'abc' not found" — descriptive and actionable.
    super(`${resource} '${id}' not found`, 404);
    this.name = 'NotFoundError';
  }
}

/**
 * ValidationError — Client sent invalid data (400).
 *
 * WHY separate class: Validation errors carry a `details` array so the client
 * knows exactly which fields failed and why. A generic 400 would lose that info.
 */
class ValidationError extends CustomError {
  constructor(message, details = []) {
    super(message, 400);
    this.name = 'ValidationError';
    // Store field-level validation failures for structured error responses.
    this.details = details;
  }
}

/**
 * InternalServerError — Unexpected server-side failure (500).
 *
 * WHY separate class: We never want to leak internal stack traces or database
 * connection strings to API consumers. This class ensures a sanitized response.
 */
class InternalServerError extends CustomError {
  constructor(message = 'An unexpected error occurred') {
    super(message, 500, false); // false = programmer error, not operational
    this.name = 'InternalServerError';
  }
}

module.exports = { CustomError, NotFoundError, ValidationError, InternalServerError };
```

