## File 6: `src/routes/books.js`

```javascript
/**
 * books.js — Express route handlers for the /books resource.
 *
 * WHY separate route file instead of putting everything in app.js:
 *   - Scalability: As the API grows, keeping routes in one file becomes unwieldy.
 *   - Readability: Each file has a single responsibility (this one = book endpoints).
 *   - Testability: Route handlers can be tested independently from middleware.
 *
 * WHY we use async/await instead of .then() chains:
 *   - Async/await is more readable and closer to synchronous thinking.
 *   - It makes error handling with try/catch natural and explicit.
 *   - Even though this example uses in-memory storage (synchronous), using
 *     async/await prepares the code for when we switch to a real database.
 *
 * WHY we use express.Router():
 *   - It allows us to mount these routes at /books without repeating the prefix.
 *   - It keeps route definitions clean and focused.
 */

const express = require('express');
const router = express.Router();

// Import our in-memory data store (abstraction layer).
const { getAllBooks, getBookById, addBook, updateBook, deleteBook, getStats } = require('../data/books');

// Import custom error classes for structured error responses.
const { NotFoundError } = require('../errors/CustomError');

// Import validation middleware to keep route handlers clean.
const { validateCreateBook, validateUpdateBook } = require('../middleware/validator');

/**
 * GET /books
 *
 * Lists all books with optional filtering by genre and/or year range.
 *
 * QUERY PARAMETERS:
 *   - genre (string): Filter by book genre (case-insensitive).
 *   - minYear (number): Include only books published on or after this year.
 *   - maxYear (number): Include only books published on or before this year.
 *
 * EXAMPLES:
 *   GET /books                          → returns all books
 *   GET /books?genre=Fiction            → returns only Fiction books
 *   GET /books?minYear=1950&maxYear=2000 → returns books from 1950-2000
 *
 * HTTP STATUS CODES:
 *   200 OK — Success, returns array of books.
 */
router.get('/', (req, res) => {
  // Destructure query parameters with fallbacks to undefined (no filter applied).
  const { genre, minYear, maxYear } = req.query;

  // Start with the full list and progressively filter.
  // This is more readable than building a complex single query.
  let result = getAllBooks();

  // Filter by genre if provided (case-insensitive comparison).
  if (genre) {
    result = result.filter(book =>
      book.genre && book.genre.toLowerCase() === genre.toLowerCase()
    );
  }

  // Filter by minimum year if provided.
  if (minYear) {
    const min = parseInt(minYear, 10);
    result = result.filter(book => book.year >= min);
  }

  // Filter by maximum year if provided.
  if (maxYear) {
    const max = parseInt(maxYear, 10);
    result = result.filter(book => book.year <= max);
  }

  // Return the filtered (or full) list with a 200 status.
  // We wrap in { success: true, data: ... } for a consistent API response format.
  res.json({
    success: true,
    count: result.length,
    data: result,
  });
});

/**
 * GET /books/:id
 *
 * Retrieves a single book by its numeric ID.
 *
 * URL PARAMETER:
 *   - id (string): The book's unique identifier (converted to number internally).
 *
 * EXAMPLES:
 *   curl http://localhost:3000/books/1
 *
 * HTTP STATUS CODES:
 *   200 OK       — Book found, returns the book object.
 *   404 Not Found — No book exists with the given ID.
 *   400 Bad Request — Invalid ID format (not a positive integer).
 */
router.get('/:id', (req, res, next) => {
  // Parse the ID from the URL parameter and validate it's a positive integer.
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    // Throw ValidationError so the global error handler formats the response.
    return next(new Error('Invalid book ID format. Must be a positive integer.'));
  }

  // Look up the book in our data store.
  const book = getBookById(id);

  if (!book) {
    // Throw NotFoundError — the global error handler will return 404 with details.
    return next(new NotFoundError('Book', id));
  }

  res.json({
    success: true,
    data: book,
  });
});

/**
 * POST /books
 *
 * Creates a new book from the request body.
 *
 * REQUEST BODY (JSON):
 *   - title (string, required): The book's title.
 *   - author (string, required): The book's author.
 *   - isbn (string, optional): ISBN-13 identifier.
 *   - year (number, optional): Publication year.
 *   - genre (string, optional): Book genre/category.
 *
 * EXAMPLE:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"Dystopian"}'
 *
 * HTTP STATUS CODES:
 *   201 Created — Book successfully created, returns the new book object.
 *   400 Bad Request — Validation failed (missing fields, wrong types).
 */
router.post('/', validateCreateBook, async (req, res, next) => {
  try {
    // Destructure to get only the fields we care about (ignore extras for safety).
    const { title, author, isbn, year, genre } = req.body;

    // Create the book in our data store.
    const newBook = addBook({ title, author, isbn, year, genre });

    // 201 Created is the standard status for resource creation.
    // It tells the client "the request succeeded and a new resource was created."
    res.status(201).json({
      success: true,
      message: 'Book created successfully',
      data: newBook,
    });
  } catch (error) {
    // Pass any unexpected errors to the global error handler.
    next(error);
  }
});

/**
 * PUT /books/:id
 *
 * Fully updates an existing book by ID. All fields in the request body replace
 * the corresponding fields in the stored book.
 *
 * URL PARAMETER:
 *   - id (string): The book's unique identifier.
 *
 * REQUEST BODY (JSON, all fields optional but at least one required):
 *   - title (string): Updated title.
 *   - author (string): Updated author.
 *   - isbn (string): Updated ISBN.
 *   - year (number): Updated publication year.
 *   - genre (string): Updated genre.
 *
 * EXAMPLE:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated Edition)"}'
 *
 * HTTP STATUS CODES:
 *   200 OK       — Book successfully updated, returns the updated book.
 *   400 Bad Request — Validation failed or invalid ID format.
 *   404 Not Found — No book exists with the given ID.
 */
router.put('/:id', validateUpdateBook, async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id <= 0) {
      return next(new Error('Invalid book ID format. Must be a positive integer.'));
    }

    // Check the book exists before attempting update.
    const existingBook = getBookById(id);
    if (!existingBook) {
      return next(new NotFoundError('Book', id));
    }

    // Update only the provided fields (partial update).
    const updatedBook = updateBook(id, req.body);

    res.json({
      success: true,
      message: 'Book updated successfully',
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * DELETE /books/:id
 *
 * Deletes a book by its ID.
 *
 * URL PARAMETER:
 *   - id (string): The book's unique identifier.
 *
 * EXAMPLE:
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * HTTP STATUS CODES:
 *   200 OK       — Book successfully deleted, returns the deleted book.
 *   400 Bad Request — Invalid ID format.
 *   404 Not Found — No book exists with the given ID.
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id <= 0) {
      return next(new Error('Invalid book ID format. Must be a positive integer.'));
    }

    const existingBook = getBookById(id);
    if (!existingBook) {
      return next(new NotFoundError('Book', id));
    }

    // Delete the book from our data store.
    deleteBook(id);

    // 200 OK with the deleted resource is a common pattern (some APIs use 204 No Content).
    // We return 200 + the deleted object so the client can confirm what was removed.
    res.json({
      success: true,
      message: 'Book deleted successfully',
      data: existingBook,
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

