```javascript
/**
 * stats.js — Route handlers for API statistics endpoints.
 *
 * WHY a separate route file for stats:
 *   - Stats are a distinct concern from book CRUD operations.
 *   - It keeps the books route focused on resource management.
 *   - It demonstrates how to organize multiple route files in an Express app.
 */

const express = require('express');
const router = express.Router();

// Import statistics function from our data layer.
const { getStats } = require('../data/books');

/**
 * GET /stats
 *
 * Returns aggregate statistics about the book collection.
 *
 * This endpoint does NOT require authentication or validation middleware
 * because it only reads pre-computed aggregates (no user input to sanitize).
 *
 * RESPONSE BODY:
 *   {
 *     success: true,
 *     data: {
 *       totalBooks: 3,
 *       genreDistribution: { Fiction: 2, Science: 1 },
 *       oldestPublicationYear: 1925,
 *       newestPublicationYear: 1988
 *     }
 *   }
 *
 * EXAMPLES:
 *   curl http://localhost:3000/stats
 *
 * HTTP STATUS CODES:
 *   200 OK — Success, returns statistics object.
 */
router.get('/', (req, res) => {
  const stats = getStats();

  res.json({
    success: true,
    data: stats,
  });
});

module.exports = router;
