## Arquivo 3: `src/middleware/errorHandler.js` — Middleware de Tratamento de Erros

```javascript
/**
 * ============================================================
 *  MÓDULO: errorHandler.js
 *  DESCRIÇÃO: Middleware centralizado de tratamento de erros.
 *
 *  POR QUE UM MIDDLEWARE DE ERROS?
 *  ---------------------------------
 *  No Express, middlewares de erro têm uma assinatura especial:
 *    (err, req, res, next) => { ... }
 *  O Express os identifica pelo número de parâmetros e os encadeia
 *  automaticamente quando um erro é passado via next(err).
 *
 *  Este middleware centraliza toda a lógica de formatação de resposta
 *  de erro, evitando repetição em cada rota. Ele também separa erros
 *  operacionais (4xx) de erros não operacionais (5xx), logando apenas
 *  estes últimos no servidor — uma prática essencial de segurança.
 * ============================================================
 */

const { InternalError } = require("../errors");

/**
 * Middleware de tratamento de erros da API.
 *
 * @param {Error} err - O erro capturado (deve ter statusCode e isOperational).
 * @param {import('express').Request} req - Objeto de requisição do Express.
 * @param {import('express').Response} res - Objeto de resposta do Express.
 * @param {import('express').NextFunction} next - Função para encaminhar ao próximo middleware.
 */
const errorHandler = (err, req, res, next) => {
  // Se o erro não tiver statusCode definido, trata como erro interno genérico
  if (!err.statusCode) {
    err = new InternalError(err.message || "Erro inesperado");
  }

  // Log apenas erros não operacionais (bugs do servidor) no console do servidor.
  // Erros operacionais (4xx) são esperados e não precisam de log de bug.
  if (!err.isOperational) {
    console.error("[ERRO DO SERVIDOR]", {
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.originalUrl,
      message: err.message,
      stack: err.stack, // Stack trace completo apenas para erros do servidor
    });
  }

  // Monta a resposta de erro padronizada
  const response = {
    success: false,
    error: {
      // Para erros operacionais (4xx), enviamos a mensagem ao cliente.
      // Para erros não operacionais (5xx), enviamos mensagem genérica por segurança.
      message: err.isOperational ? err.message : "Erro interno do servidor",
      statusCode: err.statusCode,
    },
  };

  // Em desenvolvimento, incluímos o stack trace para facilitar debugging
  if (process.env.NODE_ENV === "development") {
    response.error.stack = err.stack;
  }

  // Envia a resposta com o código de status apropriado
  res.status(err.statusCode).json(response);
};

/**
 * Middleware que captura erros de rotas assíncronas.
 *
 * PROBLEMA QUE RESOLVE:
 * --------------------
 * Express NÃO captura automaticamente rejeições de promessas em handlers async.
 * Se um handler async lança um erro, a promessa é rejeitada silenciosamente
 * e o cliente nunca recebe uma resposta (a requisição fica pendente).
 *
 * SOLUÇÃO: Envolver cada handler async com esta função que captura rejeições
 * e as encaminha para o middleware de erro via next(err).
 *
 * @param {Function} fn - Handler assíncrono Express.
 * @returns {Function} Função wrapper que captura erros assíncronos.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

module.exports = { errorHandler, asyncHandler };
```

