## Arquivo 4: `src/routes/books.js` — Rotas da API de Livros

```javascript
/**
 * ============================================================
 *  MÓDULO: routes/books.js
 *  DESCRIÇÃO: Rotas REST para gerenciamento de livros.
 *
 *  POR QUE ROTAS SEPARADAS?
 *  -------------------------
 *  Separar rotas em módulos distintos melhora a manutenibilidade,
 *  permite testar cada recurso isoladamente e segue o princípio de
 *  responsabilidade única (Single Responsibility Principle).
 *
 *  PADRÃO REST UTILIZADO:
 *  - GET    /books       → Listar todos os livros (com filtragem opcional)
 *  - GET    /books/:id   → Obter um livro pelo ID
 *  - POST   /books       → Criar um novo livro
 *  - PUT    /books/:id   → Atualizar completamente um livro
 *  - DELETE /books/:id   → Excluir um livro
 *  - GET    /stats       → Estatísticas agregadas dos livros
 *
 *  CONVENÇÕES REST ADOPTADAS:
 *  - URLs usam substantivos no plural (/books), não verbos.
 *  - Métodos HTTP indicam a ação (GET=ler, POST=criar, PUT=atualizar, DELETE=remover).
 *  - Respostas seguem formato JSON consistente com campo "data" e "error".
 *  - IDs são numéricos autoincrementais para simplicidade educacional.
 * ============================================================
 */

const { Router } = require("express");
const {
  BadRequestError,
  NotFoundError,
  ConflictError,
} = require("../errors");
const { asyncHandler } = require("../middleware/errorHandler");

// =====================================================================
//  ESTRUTURA DE DADOS EM MEMÓRIA
// =====================================================================
//
// POR QUE UM ARRAY?
// -----------------
// Para este exemplo educacional, usamos um array em memória porque:
//   1. Simplicidade: não requer configuração de banco de dados.
//   2. Transparência: o estudante pode ver todos os dados no código.
//   3. Performance suficiente para poucos registros.
//
// POR QUE OBJETOS COM PROPRIEDADES ESPECÍFICAS?
// ----------------------------------------------
// Cada livro é um objeto com campos bem definidos:
//   - id: identificador numérico único (autoincremental).
//   - title: título do livro (obrigatório, string).
//   - author: autor (obrigatório, string).
//   - year: ano de publicação (número, opcional).
//   - genre: gênero literário (string, opcional).
//   - createdAt: timestamp de criação (Date).
//   - updatedAt: timestamp da última atualização (Date).
//
// Usamos Date para timestamps porque permite ordenação e cálculo de
// diferenças de tempo. O campo updatedAt suporta auditoria básica.

/** Array que armazena todos os livros em memória. */
const books = [];

/** Contador autoincremental para gerar IDs únicos. */
let nextId = 1;

// =====================================================================
//  CRIAR INSTÂNCIA DO ROUTER
// =====================================================================
const router = Router();

// =====================================================================
//  GET /books — Listar todos os livros com filtragem opcional
// =====================================================================
/**
 * Lista todos os livros, com suporte a filtragem por query parameters.
 *
 * QUERY PARAMETERS (opcionais):
 *   - author: filtra por autor (case-insensitive, substring match).
 *   - genre:  filtra por gênero (case-insensitive, substring match).
 *   - year:   filtra por ano exato de publicação.
 *   - sort:   ordenação por campo ("title", "year", "author").
 *             prefixo "-" para ordem decrescente (ex: "-year").
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": [
 *     { "id": 1, "title": "...", "author": "...", ... }
 *   ],
 *   "total": 42
 * }
 *
 * EXEMPLO DE REQUISIÇÃO (curl):
 *   curl http://localhost:3000/books?author=tolkien&sort=-year
 *
 * EXEMPLO DE REQUISIÇÃO (Postman):
 *   GET http://localhost:3000/books
 *   Query Params: author=tolkien, sort=-year
 */
router.get(
  "/books",
  asyncHandler(async (req, res) => {
    // Desestrutura os query parameters da URL
    const { author, genre, year, sort } = req.query;

    // Começa com uma cópia do array para não mutar o original
    let result = [...books];

    // Aplica filtros se forem fornecidos (case-insensitive)
    if (author) {
      result = result.filter((book) =>
        book.author.toLowerCase().includes(author.toLowerCase())
      );
    }
    if (genre) {
      result = result.filter((book) =>
        book.genre.toLowerCase().includes(genre.toLowerCase())
      );
    }
    if (year) {
      const yearNum = parseInt(year, 10);
      if (!isNaN(yearNum)) {
        result = result.filter((book) => book.year === yearNum);
      }
    }

    // Aplica ordenação se especificada
    if (sort) {
      const descending = sort.startsWith("-");
      const field = descending ? sort.slice(1) : sort;

      result.sort((a, b) => {
        if (a[field] < b[field]) return descending ? 1 : -1;
        if (a[field] > b[field]) return descending ? -1 : 1;
        return 0;
      });
    }

    // Retorna os livros com contagem total
    res.json({
      success: true,
      data: result,
      total: result.length,
    });
  })
);

// =====================================================================
//  GET /books/:id — Obter um livro pelo ID
// =====================================================================
/**
 * Retorna um único livro identificado pelo parâmetro de URL :id.
 *
 * PARÂMETRO DE URL:
 *   - id: identificador numérico do livro.
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "...", ... }
 * }
 *
 * RESPOSTA DE ERRO (404 Not Found):
 * {
 *   "success": false,
 *   "error": { "message": "Livro não encontrado", "statusCode": 404 }
 * }
 *
 * EXEMPLO DE REQUISIÇÃO (curl):
 *   curl http://localhost:3000/books/1
 *
 * EXEMPLO DE REQUISIÇÃO (Postman):
 *   GET http://localhost:3000/books/1
 */
router.get(
  "/books/:id",
  asyncHandler(async (req, res) => {
    // Converte o ID de string (URL) para número
    const id = parseInt(req.params.id, 10);

    // Busca o livro pelo ID usando find (O(n) — aceitável para array pequeno)
    const book = books.find((b) => b.id === id);

    // Se não encontrado, lança NotFoundError (capturado pelo middleware de erro)
    if (!book) {
      throw new NotFoundError("Livro");
    }

    res.json({ success: true, data: book });
  })
);

// =====================================================================
//  POST /books — Criar um novo livro
// =====================================================================
/**
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * {
 *   "title": "O Senhor dos Anéis",    // obrigatório, string não vazia
 *   "author": "J.R.R. Tolkien",       // obrigatório, string não vazia
 *   "year": 1954,                     // opcional, número
 *   "genre": "Fantasia"               // opcional, string
 * }
 *
 * RESPOSTA DE SUCESSO (201 Created):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "...", ... }
 * }
 *
 * RESPOSTA DE ERRO (400 Bad Request) — se title ou author faltarem:
 * {
 *   "success": false,
 *   "error": { "message": "Title e author são campos obrigatórios", "statusCode": 400 }
 * }
 *
 * EXEMPLO DE REQUISIÇÃO (curl):
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"Distopia"}'
 *
 * EXEMPLO DE REQUISIÇÃO (Postman):
 *   POST http://localhost:3000/books
 *   Headers: Content-Type: application/json
 *   Body (JSON): {"title":"1984","author":"George Orwell","year":1949,"genre":"Distopia"}
 */
router.post(
  "/books",
  asyncHandler(async (req, res) => {
    const { title, author, year, genre } = req.body;

    // Validação: title e author são obrigatórios
    if (!title || !author) {
      throw new BadRequestError("Title e author são campos obrigatórios");
    }

    // Cria o novo livro com ID autoincremental e timestamps
    const newBook = {
      id: nextId++, // Incrementa e atribui o ID atual
      title,
      author,
      year: year ? parseInt(year, 10) : null,
      genre: genre || null,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Adiciona ao array (O(1) — push no final)
    books.push(newBook);

    // Retorna 201 Created com o livro criado
    res.status(201).json({ success: true, data: newBook });
  })
);

// =====================================================================
//  PUT /books/:id — Atualizar completamente um livro
// =====================================================================
/**
 * Atualiza TODOS os campos de um livro existente (substituição completa).
 *
 * PARÂMETRO DE URL:
 *   - id: identificador numérico do livro a atualizar.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * {
 *   "title": "Novo Título",
 *   "author": "Novo Autor",
 *   "year": 2024,
 *   "genre": "Ficção Científica"
 * }
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "Novo Título", ... }
 * }
 *
 * EXEMPLO DE REQUISIÇÃO (curl):
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis - Edição Especial","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 *
 * EXEMPLO DE REQUISIÇÃO (Postman):
 *   PUT http://localhost:3000/books/1
 *   Headers: Content-Type: application/json
 *   Body (JSON): {"title":"O Senhor dos Anéis - Edição Especial","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}
 */
router.put(
  "/books/:id",
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const index = books.findIndex((b) => b.id === id);

    // Verifica se o livro existe antes de atualizar
    if (index === -1) {
      throw new NotFoundError("Livro");
    }

    const { title, author, year, genre } = req.body;

    // Validação: title e author são obrigatórios mesmo na atualização
    if (!title || !author) {
      throw new BadRequestError("Title e author são campos obrigatórios");
    }

    // Atualiza todos os campos (substituição completa — PUT semântico)
    books[index] = {
      ...books[index], // Preserva o id e outros campos não enviados
      title,
      author,
      year: year ? parseInt(year, 10) : null,
      genre: genre || null,
      updatedAt: new Date(), // Atualiza timestamp de modificação
    };

    res.json({ success: true, data: books[index] });
  })
);

// =====================================================================
//  DELETE /books/:id — Excluir um livro
// =====================================================================
/**
 * Remove permanentemente um livro do array pelo seu ID.
 *
 * PARÂMETRO DE URL:
 *   - id: identificador numérico do livro a excluir.
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": { "id": 1, "title": "...", ... }  // Retorna o livro excluído
 * }
 *
 * RESPOSTA DE ERRO (404 Not Found):
 * {
 *   "success": false,
 *   "error": { "message": "Livro não encontrado", "statusCode": 404 }
 * }
 *
 * EXEMPLO DE REQUISIÇÃO (curl):
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * EXEMPLO DE REQUISIÇÃO (Postman):
 *   DELETE http://localhost:3000/books/1
 */
router.delete(
  "/books/:id",
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);
    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      throw new NotFoundError("Livro");
    }

    // Splice remove o elemento e retorna um array com ele (O(n))
    const [deletedBook] = books.splice(index, 1);

    res.json({ success: true, data: deletedBook });
  })
);

// =====================================================================
//  GET /stats — Estatísticas agregadas dos livros
// =====================================================================
/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * RESPOSTA DE SUCESSO (200 OK):
 * {
 *   "success": true,
 *   "data": {
 *     "totalBooks": 42,
 *     "totalAuthors": 30,
 *     "averageYear": 1998.5,
 *     "booksByGenre": { "Fantasia": 15, "Distopia": 8 },
 *     "newestBook": { "id": 42, "title": "...", "createdAt": "..." },
 *     "oldestBook": { "id": 1, "title": "...", "createdAt": "..." }
 *   }
 * }
 *
 * EXEMPLO DE REQUISIÇÃO (curl):
 *   curl http://localhost:3000/stats
 *
 * EXEMPLO DE REQUISIÇÃO (Postman):
 *   GET http://localhost:3000/stats
 */
router.get(
  "/stats",
  asyncHandler(async (req, res) => {
    const totalBooks = books.length;

    // Calcula autores únicos usando Set (remove duplicatas automaticamente)
    const uniqueAuthors = new Set(books.map((b) => b.author)).size;

    // Calcula a média dos anos de publicação (ignorando livros sem year)
    const booksWithYear = books.filter((b) => b.year !== null);
    const averageYear =
      booksWithYear.length > 0
        ? booksWithYear.reduce((sum, b) => sum + b.year, 0) /
          booksWithYear.length
        : null;

    // Conta livros por gênero usando reduce (O(n))
    const booksByGenre = books.reduce((acc, book) => {
      const genre = book.genre || "Sem gênero";
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Encontra o livro mais recente e mais antigo por timestamp de criação
    const newestBook =
      books.length > 0
        ? books.reduce((latest, book) =>
            new Date(book.createdAt) > new Date(latest.createdAt) ? book : latest
          )
        : null;

    const oldestBook =
      books.length > 0
        ? books.reduce((earliest, book) =>
            new Date(book.createdAt) < new Date(earliest.createdAt)
              ? book
              : earliest
          )
        : null;

    res.json({
      success: true,
      data: {
        totalBooks,
        totalAuthors: uniqueAuthors,
        averageYear: averageYear ? Math.round(averageYear * 100) / 100 : null,
        booksByGenre,
        newestBook,
        oldestBook,
      },
    });
  })
);

// =====================================================================
//  EXPORTAÇÃO DO ROUTER
// =====================================================================
module.exports = router;
```

