/**
 * books.js — In-memory data store for books.
 *
 * WHY an in-memory array instead of a database:
 *   - Keeps the example self-contained with zero external dependencies.
 *   - Makes it easy to see exactly how CRUD operations work under the hood.
 *   - In production, you would replace this module with a database adapter
 *     (e.g., MongoDB, PostgreSQL) — the route handlers wouldn't need to change
 *     because we abstract the storage layer here.
 *
 * WHY an array of objects instead of a Map:
 *   - Arrays are simpler for a tutorial and support ordered iteration.
 *   - A Map would be slightly more efficient for lookups by ID, but for a small
 *     educational dataset the difference is negligible.
 *   - We maintain a separate `nextId` counter to generate unique IDs without
 *     relying on external libraries like UUID.
 *
 * WHY seed data:
 *   - Provides immediate visible results when the API starts, making it easier
 *     to test and demonstrate functionality without first creating books.
 */

// In-memory array holding all book records.
// Each book is an object with a unique numeric ID and standard properties.
let books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    isbn: '978-0743273565',
    year: 1925,
    genre: 'Fiction',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    isbn: '978-0061120084',
    year: 1960,
    genre: 'Fiction',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    isbn: '978-0553380163',
    year: 1988,
    genre: 'Science',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
];

// Counter for generating unique IDs. Starts at the max existing ID + 1.
// This avoids collisions with seeded data and is simpler than importing a UUID library.
let nextId = books.length > 0 ? Math.max(...books.map(b => b.id)) + 1 : 1;

/**
 * getAllBooks — Returns the full list of books.
 *
 * @returns {Array<Object>} Array of book objects.
 */
function getAllBooks() {
  return books;
}

/**
 * getBookById — Finds a book by its numeric ID.
 *
 * @param {number} id — The unique identifier of the book.
 * @returns {Object|null} The book object if found, null otherwise.
 */
function getBookById(id) {
  return books.find(book => book.id === id) || null;
}

/**
 * addBook — Creates a new book and appends it to the array.
 *
 * @param {Object} bookData — The book data (without id, createdAt, updatedAt).
 * @returns {Object} The newly created book with generated ID and timestamps.
 */
function addBook(bookData) {
  const now = new Date().toISOString();
  const newBook = {
    id: nextId++,          // Increment and assign — simple auto-increment strategy.
    ...bookData,           // Spread the provided fields into the book object.
    createdAt: now,        // ISO 8601 timestamp for auditability.
    updatedAt: now,
  };
  books.push(newBook);
  return newBook;
}

/**
 * updateBook — Updates an existing book by ID with partial data.
 *
 * @param {number} id — The unique identifier of the book to update.
 * @param {Object} updates — Fields to update (partial object).
 * @returns {Object|null} The updated book if found, null if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return null;

  // Update only the fields that were provided (partial update / PATCH semantics).
  // We explicitly list allowed fields to prevent injecting unauthorized properties.
  const allowedFields = ['title', 'author', 'isbn', 'year', 'genre'];
  for (const field of allowedFields) {
    if (updates[field] !== undefined) {
      books[index][field] = updates[field];
    }
  }
  books[index].updatedAt = new Date().toISOString();
  return books[index];
}

/**
 * deleteBook — Removes a book by ID.
 *
 * @param {number} id — The unique identifier of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  // splice removes the element at `index` and shifts subsequent elements down.
  // This maintains array continuity after deletion.
  books.splice(index, 1);
  return true;
}

/**
 * getStats — Returns aggregate statistics about the book collection.
 *
 * @returns {Object} Statistics including total count, genre distribution, etc.
 */
function getStats() {
  const totalBooks = books.length;

  // Count occurrences of each genre using a reduce accumulator.
  // This gives us a quick breakdown of the collection's diversity.
  const genreDistribution = books.reduce((acc, book) => {
    const genre = book.genre || 'Unknown';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Find the oldest and newest books by year.
  const years = books.map(b => b.year).filter(y => typeof y === 'number');
  const oldestYear = years.length > 0 ? Math.min(...years) : null;
  const newestYear = years.length > 0 ? Math.max(...years) : null;

  return {
    totalBooks,
    genreDistribution,
    oldestPublicationYear: oldestYear,
    newestPublicationYear: newestYear,
  };
}

module.exports = { getAllBooks, getBookById, addBook, updateBook, deleteBook, getStats };
