/**
 * index.js — Application entry point.
 *
 * WHY this is the single entry point:
 *   - Express apps should have one central file that wires everything together.
 *   - It makes it clear what middleware is loaded and in what order.
 *   - The startup message confirms the server is ready for requests.
 *
 * MIDDLEWARE ORDER MATTERS in Express:
 *   1. Body parsing (express.json) — must come BEFORE route handlers that read req.body.
 *   2. Request logging (morgan or custom) — logs every incoming request.
 *   3. Route definitions — handled in order they are registered.
 *   4. Error handler (4-param function) — MUST be last; catches errors from all routes.
 *   5. 404 catch-all — catches requests that don't match any route.
 */

const express = require('express');

// Import our custom error handler middleware.
const errorHandler = require('./middleware/errorHandler');

// Import route modules.
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Create the Express application instance.
const app = express();

// ──────────────────────────────────────────────
// Middleware Configuration
// ──────────────────────────────────────────────

/**
 * express.json() — Parses incoming JSON request bodies.
 *
 * WHY this is essential: Without it, req.body would be undefined and we couldn't
 * read POST/PUT data. The `limit` option prevents abuse via excessively large payloads.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Custom request logger — prints method, URL, and timestamp for each request.
 *
 * WHY a simple logger instead of morgan for this example:
 *   - Keeps dependencies minimal (no extra npm package needed).
 *   - Demonstrates how Express middleware works under the hood.
 *   - In production, you'd use morgan + a logging service.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler.
});

// ──────────────────────────────────────────────
// Route Registration
// ──────────────────────────────────────────────

/**
 * Mount book routes at /books.
 *
 * WHY app.use('/books', bookRoutes) instead of prefixing each route:
 *   - DRY: The prefix is defined once, not repeated in every router.get/post/etc.
 *   - Organization: It's immediately clear which routes belong to which resource.
 */
app.use('/books', bookRoutes);

/**
 * Mount stats routes at /stats.
 */
app.use('/stats', statsRoutes);

// ──────────────────────────────────────────────
// Root Endpoint
// ──────────────────────────────────────────────

/**
 * GET / — API health check and documentation endpoint.
 *
 * WHY include a root endpoint:
 *   - It gives clients a starting point to discover available endpoints.
 *   - It's useful for load balancers and health checks.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API is running',
    endpoints: {
      books: {
        GET: '/books',
        GET_one: '/books/:id',
        POST: '/books',
        PUT: '/books/:id',
        DELETE: '/books/:id',
      },
      stats: {
        GET: '/stats',
      },
    },
  });
});

// ──────────────────────────────────────────────
// 404 Catch-All — Must come AFTER all route definitions.
// ──────────────────────────────────────────────

/**
 * Catches requests to undefined routes and returns a 404.
 *
 * WHY this is needed: Without it, Express would return its default "Cannot GET /foo" HTML.
 * Our JSON-formatted 404 is consistent with the rest of the API.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      type: 'NotFoundError',
      message: `Route ${req.method} ${req.url} not found`,
    },
  });
});

// ──────────────────────────────────────────────
// Global Error Handler — MUST be the last middleware.
// ──────────────────────────────────────────────

/**
 * errorHandler(err, req, res, next) — Catches all errors thrown in routes/middleware.
 *
 * WHY it must be last: Express processes middleware in order. If placed before
 * route handlers, it would intercept normal responses as errors. The 4-parameter
 * signature is Express's signal that this is an error handler, not regular middleware.
 */
app.use(errorHandler);

// ──────────────────────────────────────────────
// Server Startup
// ──────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book REST API running on http://localhost:${PORT}`);
  console.log(`   Endpoints:`);
  console.log(`     GET    http://localhost:${PORT}/          — API info`);
  console.log(`     GET    http://localhost:${PORT}/books     — List all books`);
  console.log(`     GET    http://localhost:${PORT}/books/:id — Get single book`);
  console.log(`     POST   http://localhost:${PORT}/books     — Create a book`);
  console.log(`     PUT    http://localhost:${PORT}/books/:id — Update a book`);
  console.log(`     DELETE http://localhost:${PORT}/books/:id — Delete a book`);
  console.log(`     GET    http://localhost:${PORT}/stats     — Get statistics`);
});

module.exports = app;
