## Arquivo 5: `src/app.js` — Aplicação Principal

```javascript
/**
 * ============================================================
 *  ARQUIVO: app.js
 *  DESCRIÇÃO: Ponto de entrada da aplicação Express.
 *
 *  POR QUE SEPARAR app.js DO SERVER.JS?
 *  --------------------------------------
 *  Em projetos maiores, separamos a configuração do app (middlewares,
 *  rotas) do listen (porta de rede). Aqui mantemos tudo em um arquivo
 *  por simplicidade educacional.
 *
 *  FLUXO DE EXECUÇÃO:
 *  1. Importar dependências (express, módulos internos).
 *  2. Criar instância do Express.
 *  3. Configurar middlewares globais (JSON parsing, CORS, logging).
 *  4. Registrar rotas.
 *  5. Registrar middleware de tratamento de erros (deve ser o último).
 *  6. Iniciar servidor na porta configurada.
 * ============================================================
 */

const express = require("express");
const bookRoutes = require("./routes/books");
const { errorHandler } = require("./middleware/errorHandler");

// =====================================================================
//  CRIAR INSTÂNCIA DO EXPRESS
// =====================================================================
const app = express();

// =====================================================================
//  CONFIGURAR MIDDLEWARES GLOBAIS
// =====================================================================

/**
 * Middleware body-parser do Express.
 *
 * Por quê? Para que req.body contenha os dados JSON enviados pelo cliente.
 * Sem este middleware, req.body seria undefined.
 */
app.use(express.json());

/**
 * Middleware CORS básico.
 *
 * Por quê? Permite que requisições de diferentes origens (ex: frontend React
 * rodando em localhost:3001) acessem esta API. Em produção, restrinja o
 * origin para maior segurança.
 */
app.use((req, res, next) => {
  res.header("Access-Control-Allow-Origin", "*");
  res.header(
    "Access-Control-Allow-Headers",
    "Origin, X-Requested-With, Content-Type, Accept, Authorization"
  );
  res.header(
    "Access-Control-Allow-Methods",
    "GET, POST, PUT, DELETE, OPTIONS"
  );

  // Responde imediatamente a requisições OPTIONS (preflight CORS)
  if (req.method === "OPTIONS") {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Middleware de logging simples.
 *
 * Por quê? Facilita o debugging ao ver cada requisição no console.
 * Em produção, considere usar bibliotecas como 'morgan' ou 'pino'.
 */
app.use((req, res, next) => {
  console.log(
    `[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`
  );
  next();
});

// =====================================================================
//  REGISTRAR ROTAS
// =====================================================================

/**
 * Por que usar router?
 * --------------------
 * O Router do Express permite agrupar rotas relacionadas e aplicar
 * middlewares específicos a grupos de rotas. Neste caso, todas as
 * rotas de livros são montadas sob o prefixo "/api".
 *
 * Isso também facilita a escalabilidade: se adicionarmos outro recurso
 * (autores, editoras), criamos novos routers e os montamos separadamente.
 */
app.use("/api", bookRoutes);

// =====================================================================
//  ROTA DE HEALTH CHECK
// =====================================================================
/**
 * Endpoint simples para verificar se a API está respondendo.
 * Útil para monitoramento (health checks) e testes iniciais.
 */
app.get("/health", (req, res) => {
  res.json({ status: "ok", timestamp: new Date().toISOString() });
});

// =====================================================================
//  ROTA 404 PARA ROTAS NÃO ENCONTRADAS
// =====================================================================
/**
 * Middleware que captura requisições para rotas não definidas.
 *
 * Por quê? Sem este middleware, o Express retornaria um erro genérico
 * do navegador ("Cannot GET /foo"). Com ele, fornecemos uma resposta
 * JSON consistente e profissional.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Rota ${req.method} ${req.originalUrl} não encontrada`,
      statusCode: 404,
    },
  });
});

// =====================================================================
//  MIDDLEWARE DE TRATAMENTO DE ERROS (DEVE SER O ÚLTIMO)
// =====================================================================
/**
 * Por que este middleware deve ser o último?
 * -------------------------------------------
 * No Express, middlewares são executados em ordem. O middleware de erro
 * precisa vir após TODOS os outros para capturar erros de qualquer rota
 * ou middleware anterior. Sua assinatura com 4 parâmetros (err, req, res, next)
 * é o que o Express reconhece como middleware de erro.
 */
app.use(errorHandler);

// =====================================================================
//  INICIAR O SERVIDOR
// =====================================================================
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════╗
║     API de Livros — Servidor rodando na porta ${PORT}   ║
║                                                      ║
║  Health Check:  http://localhost:${PORT}/health        ║
║  Listar livros: http://localhost:${PORT}/api/books      ║
║  Estatísticas:  http://localhost:${PORT}/api/stats      ║
╚══════════════════════════════════════════════════════╝
  `);
});

module.exports = app;
```

