/**
 * errorHandler.js — Global Express error-handling middleware.
 *
 * WHY a single centralized handler instead of try/catch in every route:
 *   - DRY: One place to format error responses consistently.
 *   - Catch-all: Express passes errors to this via next(err) automatically,
 *     so even async errors that slip through are caught.
 *   - Production safety: We never expose internal details (stack traces, DB URLs).
 *
 * Express identifies error-handling middleware by its 4-parameter signature:
 *   (err, req, res, next) => ...
 * Middleware with 3 parameters is treated as regular middleware and skipped.
 */

const { CustomError } = require('../errors/CustomError');

/**
 * errorHandler — Centralized error handler for all Express routes.
 *
 * @param {Error} err — The error object thrown by a route or middleware.
 * @param {import('express').Request} req — The HTTP request object.
 * @param {import('express').Response} res — The HTTP response object.
 * @param {import('express').NextFunction} next — Express next() function.
 */
function errorHandler(err, req, res, next) {
  // Log the full error (including stack) server-side for debugging.
  // In production, you'd send this to a logging service like Sentry or Datadog.
  console.error(`[ERROR] ${new Date().toISOString()} — ${err.name}: ${err.message}`);
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    console.error(err.stack);
  }

  // If the error is our CustomError, use its statusCode and message.
  // This preserves the intentional HTTP status codes we set in route handlers.
  if (err instanceof CustomError) {
    const response = {
      success: false,
      error: {
        type: err.name,
        message: err.message,
      },
    };

    // Include validation details so the client can fix specific fields.
    if (err.details && err.details.length > 0) {
      response.error.details = err.details;
    }

    return res.status(err.statusCode).json(response);
  }

  // For unexpected errors (bugs, crashes), return a generic 500.
  // NEVER expose the stack trace or internal message to the client — security risk.
  return res.status(500).json({
    success: false,
    error: {
      type: 'InternalServerError',
      message: process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred'
        : err.message, // In dev, show the real message for easier debugging.
    },
  });
}

module.exports = errorHandler;
```

