## File 4: `src/middleware/validator.js`

```javascript
/**
 * validator.js — Request validation middleware for book endpoints.
 *
 * WHY separate validation from route handlers:
 *   - Separation of concerns: Routes should focus on business logic, not input checking.
 *   - Reusability: The same validation can be applied across multiple routes.
 *   - Testability: Validation logic is isolated and easier to unit test.
 *
 * Each validator returns an Express middleware function that calls next(err)
 * if validation fails, which immediately jumps to the error handler.
 */

const { ValidationError } = require('../errors/CustomError');

/**
 * validateCreateBook — Validates fields required when creating a book.
 *
 * @returns {Function} Express middleware.
 *
 * REQUIRED FIELDS: title (string), author (string)
 * OPTIONAL FIELDS:  isbn (string), year (number, positive integer), genre (string)
 */
function validateCreateBook(req, res, next) {
  const errors = [];

  // Check that the request body exists.
  if (!req.body || typeof req.body !== 'object') {
    return next(new ValidationError('Request body must be a JSON object', [
      { field: 'body', message: 'Expected a JSON object in the request body' },
    ]));
  }

  const { title, author, isbn, year, genre } = req.body;

  // Title is required and must be a non-empty string.
  if (title === undefined || title === null) {
    errors.push({ field: 'title', message: 'Title is required' });
  } else if (typeof title !== 'string' || title.trim() === '') {
    errors.push({ field: 'title', message: 'Title must be a non-empty string' });
  }

  // Author is required and must be a non-empty string.
  if (author === undefined || author === null) {
    errors.push({ field: 'author', message: 'Author is required' });
  } else if (typeof author !== 'string' || author.trim() === '') {
    errors.push({ field: 'author', message: 'Author must be a non-empty string' });
  }

  // ISBN, if provided, should be a string (we don't enforce format here for simplicity).
  if (isbn !== undefined && isbn !== null && typeof isbn !== 'string') {
    errors.push({ field: 'isbn', message: 'ISBN must be a string' });
  }

  // Year, if provided, should be a positive integer.
  if (year !== undefined && year !== null) {
    if (!Number.isInteger(year) || year < 0) {
      errors.push({ field: 'year', message: 'Year must be a positive integer' });
    }
  }

  // Genre, if provided, should be a string.
  if (genre !== undefined && genre !== null && typeof genre !== 'string') {
    errors.push({ field: 'genre', message: 'Genre must be a string' });
  }

  // If any validation failed, throw a single ValidationError with all details.
  // This is more efficient than making multiple round-trips to the client.
  if (errors.length > 0) {
    return next(new ValidationError('Invalid input data', errors));
  }

  // Validation passed — proceed to the route handler.
  next();
}

/**
 * validateUpdateBook — Validates fields for updating a book (all optional).
 *
 * @returns {Function} Express middleware.
 *
 * At least one field must be provided, or we return a validation error.
 */
function validateUpdateBook(req, res, next) {
  const errors = [];
  const allowedFields = ['title', 'author', 'isbn', 'year', 'genre'];

  if (!req.body || typeof req.body !== 'object') {
    return next(new ValidationError('Request body must be a JSON object', [
      { field: 'body', message: 'Expected a JSON object in the request body' },
    ]));
  }

  // Check that at least one updatable field is present.
  const hasUpdatableField = allowedFields.some(field => req.body[field] !== undefined);
  if (!hasUpdatableField) {
    return next(new ValidationError('At least one field must be provided for update', [
      { field: 'body', message: 'Provide at least one of: title, author, isbn, year, genre' },
    ]));
  }

  const { title, author, isbn, year, genre } = req.body;

  if (title !== undefined && (typeof title !== 'string' || title.trim() === '')) {
    errors.push({ field: 'title', message: 'Title must be a non-empty string' });
  }
  if (author !== undefined && (typeof author !== 'string' || author.trim() === '')) {
    errors.push({ field: 'author', message: 'Author must be a non-empty string' });
  }
  if (isbn !== undefined && typeof isbn !== 'string') {
    errors.push({ field: 'isbn', message: 'ISBN must be a string' });
  }
  if (year !== undefined && (!Number.isInteger(year) || year < 0)) {
    errors.push({ field: 'year', message: 'Year must be a positive integer' });
  }
  if (genre !== undefined && typeof genre !== 'string') {
    errors.push({ field: 'genre', message: 'Genre must be a string' });
  }

  if (errors.length > 0) {
    return next(new ValidationError('Invalid input data', errors));
  }

  next();
}

module.exports = { validateCreateBook, validateUpdateBook };
```

