## Arquivo 2: `src/errors.js` — Classes de Erro Personalizadas

```javascript
/**
 * ============================================================
 *  MÓDULO: errors.js
 *  DESCRIÇÃO: Define classes de erro personalizadas para a API.
 *
 *  POR QUE CLASSES DE ERRO PERSONALIZADAS?
 *  -----------------------------------------
 *  Em vez de lançar erros genéricos (new Error("algo deu errado")),
 *  criamos subclasses que carregam informações estruturadas:
 *    - statusCode: código HTTP apropriado para o cliente.
 *    - isOperational: indica se o erro é esperado (ex: input inválido)
 *      vs. um bug interno do servidor (não operacional).
 *    - Mensagem legível para o cliente, sem expor detalhes internos.
 *
 *  Isso permite que o middleware de tratamento de erros distinga entre
 *  erros "operacionais" (resposta 4xx) e erros "não operacionais"
 *  (resposta 500 com log interno), uma prática recomendada em APIs
 *  profissionais (inspirado no padrão do pacote 'http-errors').
 * ============================================================
 */

/**
 * Classe base para todos os erros da API.
 * Estende Error nativo do JavaScript e adiciona propriedades HTTP.
 */
class ApiError extends Error {
  /**
   * Construtor da classe base de erro da API.
   *
   * @param {string} message - Mensagem descritiva do erro (visível ao cliente).
   * @param {number} statusCode - Código HTTP de status (ex: 400, 404, 500).
   * @param {boolean} [isOperational=true] - Se true, o erro é esperado e não logado como bug.
   */
  constructor(message, statusCode, isOperational = true) {
    super(message); // Chama o construtor da classe Error nativa

    // Captura o nome da classe para debugging (ex: "NotFoundError")
    this.name = this.constructor.name;

    // Código HTTP que será enviado na resposta
    this.statusCode = statusCode;

    // Flag operacional: erros operacionais são respostas esperadas do negócio
    // (input inválido, recurso não encontrado). Erros não operacionais indicam bugs.
    this.isOperational = isOperational;

    // Captura o stack trace no ponto de criação para melhor debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 400 Bad Request — Dados de entrada inválidos.
 *
 * Usado quando o cliente envia dados que não atendem aos requisitos do servidor.
 * Exemplo: campo obrigatório ausente, tipo errado, valor fora do intervalo.
 */
class BadRequestError extends ApiError {
  constructor(message = "Requisição inválida") {
    super(message, 400); // HTTP 400: Bad Request
  }
}

/**
 * Erro 404 Not Found — Recurso não encontrado.
 *
 * Usado quando o ID informado na URL não corresponde a nenhum livro no banco.
 */
class NotFoundError extends ApiError {
  constructor(entity = "Recurso") {
    super(`${entity} não encontrado`, 404); // HTTP 404: Not Found
  }
}

/**
 * Erro 409 Conflict — Conflito com estado atual do servidor.
 *
 * Usado quando uma operação viola uma restrição de integridade.
 * Exemplo: tentar criar um livro com ID que já existe.
 */
class ConflictError extends ApiError {
  constructor(message = "Conflito com recurso existente") {
    super(message, 409); // HTTP 409: Conflict
  }
}

/**
 * Erro 500 Internal Server Error — Falha interna do servidor.
 *
 * Usado para erros não esperadados (bugs). A mensagem exata NÃO é enviada
 * ao cliente por segurança, apenas um genérico "Erro interno do servidor".
 */
class InternalError extends ApiError {
  constructor(message = "Erro interno do servidor", isOperational = false) {
    super(message, 500, isOperational); // HTTP 500: Internal Server Error
  }
}

/**
 * Exporta todas as classes de erro como um único objeto.
 * Isso facilita a importação em outros módulos com uma única linha.
 */
module.exports = {
  ApiError,
  BadRequestError,
  NotFoundError,
  ConflictError,
  InternalError,
};
```

